WITH t AS (SELECT d.driver_id,d.driver_name,AVG(CASE WHEN MONTH(trip_date)<=6 THEN distance_km/fuel_consumed END) first_half_avg,AVG(CASE WHEN MONTH(trip_date)>=7 THEN distance_km/fuel_consumed END) second_half_avg FROM drivers d JOIN trips t ON d.driver_id=t.driver_id GROUP BY d.driver_id,d.driver_name HAVING COUNT(CASE WHEN MONTH(trip_date)<=6 THEN 1 END)>0 AND COUNT(CASE WHEN MONTH(trip_date)>=7 THEN 1 END)>0) SELECT driver_id,driver_name,ROUND(first_half_avg,2) first_half_avg,ROUND(second_half_avg,2) second_half_avg,ROUND(second_half_avg-first_half_avg,2) efficiency_improvement FROM t WHERE second_half_avg>first_half_avg ORDER BY efficiency_improvement DESC,driver_name;